From 4f2fb0fac07ea61090d7a685853c4d00cff4c77d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:58:54 +0100
Subject: [PATCH] libtaskmanager: map Steam games to their menu entries

Steam games run a binary that nothing in their .desktop file refers to,
so their tasks got a generic icon and couldn't be pinned. Steam puts the
game's app id in its environment, so match it to the entry that runs it.

BUG: 406858
---
 libtaskmanager/tasktools.cpp | 15 +++++++++++++++
 1 file changed, 15 insertions(+)

diff --git a/libtaskmanager/tasktools.cpp b/libtaskmanager/tasktools.cpp
index 98542d332f..d58b5cf447 100644
--- a/libtaskmanager/tasktools.cpp
+++ b/libtaskmanager/tasktools.cpp
@@ -238,6 +238,7 @@ KService::List servicesFromEnvironment(quint32 pid)
     if (environFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
         constexpr QByteArrayView bamfDesktopFileHint{"BAMF_DESKTOP_FILE_HINT"};
         constexpr QByteArrayView appDir{"APPDIR"};
+        constexpr QByteArrayView steamAppId{"SteamAppId"};
         const QByteArray environ = environFile.readAll();
 #if (defined(__GNUC__) && __GNUC__ >= 12) || !defined(__GNUC__)
         for (const QByteArrayView line : QByteArrayView(environ) | std::views::split('\0')) {
@@ -264,6 +265,20 @@ KService::List servicesFromEnvironment(quint32 pid)
                     return {QExplicitlySharedDataPointer<KService>(new KService(desktopFileList[0].absoluteFilePath()))};
                 }
                 break;
+            } else if (key == steamAppId) {
+                // Steam games get their app id in the environment; their menu entries run steam://rungameid/<id>.
+                bool ok = false;
+                const QByteArrayView value = line.sliced(equalsIdx + 1);
+                if (value.toULongLong(&ok) == 0 || !ok) {
+                    continue;
+                }
+                const QString gameUrl = QLatin1String("steam://rungameid/") + QString::fromLatin1(value);
+                const auto services = KApplicationTrader::query([&gameUrl](const KService::Ptr &service) {
+                    return service->exec().split(u' ', Qt::SkipEmptyParts).contains(gameUrl);
+                });
+                if (!services.isEmpty()) {
+                    return services;
+                }
             }
         }
     }
